package com.farm2market.controller;
import com.farm2market.dto.*; import com.farm2market.entity.*; import com.farm2market.repository.*; import com.farm2market.security.JwtService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {final UserRepository repo;final PasswordEncoder enc;final JwtService jwt; AuthController(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} @PostMapping("/register") public Map<String,Object> register(@Valid @RequestBody RegisterRequest x){if(repo.findByEmail(x.email()).isPresent())throw new RuntimeException("Email already registered");User u=new User();u.setName(x.name());u.setEmail(x.email());u.setPassword(enc.encode(x.password()));u.setPhone(x.phone());u.setLocation(x.location());u.setRole(x.role()==Role.FARMER?Role.FARMER:Role.BUYER);repo.save(u);return Map.of("success",true,"message","Registration successful","data",Map.of("token",jwt.create(u.getEmail(),u.getRole().name()),"user",u.getName(),"role",u.getRole()));} @PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody AuthRequest x){User u=repo.findByEmail(x.email()).orElseThrow(()->new RuntimeException("Invalid credentials"));if(!enc.matches(x.password(),u.getPassword()))throw new RuntimeException("Invalid credentials");return Map.of("success",true,"message","Login successful","data",Map.of("token",jwt.create(u.getEmail(),u.getRole().name()),"user",u.getName(),"role",u.getRole()));}}
